    d=read(BASE/'RESULTS.json');a=read(BASE/'ROOT_SCALAR_READBACK.json');assert a['status']=='pass'and a['result_sha256']==sha(BASE/'RESULTS.json');rr=read(B2/'ROSTER_LOCK.json')['records'];aliases={r['probe_alias']:f'R{i:03d}'for i,r in enumerate(rr,1)}
