    assert not (OUT/'RESULTS.json').exists();OUT.mkdir(parents=True,exist_ok=True);pub=anon(d);pairs={frozenset(x)for x in [('QC_raw_hard','MARGINAL_NO_UPDATE'),('QC_target_hard','MARGINAL_NO_UPDATE'),('Native_pair_hard','MARGINAL_NO_UPDATE'),('B_MARGINAL_DECODE','MARGINAL_NO_UPDATE'),('B_MARGINAL_DECODE','QC_target_hard'),('B_MARGINAL_DECODE','QC_raw_hard'),('QC_target_hard','QC_raw_hard'),('I2_fixed','I1_fixed')]};pub['paired']=[x for x in pub['paired']if frozenset(x['comparison'].split('_minus_'))in pairs];pub['public_pairwise_scope']='eight diagnostic pairs; complete12-arm source rows retained for all reconstructions';write(OUT/'RESULTS.json',pub);write(OUT/'ROOT_SCALAR_READBACK.json',a);write(OUT/'QUALITATIVE_TEXT_AUDIT.json',anon(read(BASE/'QUALITATIVE_TEXT_AUDIT.json')))
    write(OUT/'ACTUAL_SCOPE.json',dict(count=256,per_domain=128,source='same original exposed development parents, cross-domain TA-STVG',source_checkpoint_sha256_by_target={ds:sorted({r['source_checkpoint_sha256']for r in rr if r['dataset']==ds})for ds in ['hc2','vidstg']},Teacher='frozen STVG-R1-7B c0db00d019bf746f54b67770b82261b2161fed59',new_models=0,new_Teacher_calls=0,new_fits=0,new_GPU_forwards=0,new_video_decodes=0,GT_only_posthoc_diagnostic=True,all_predictions_sealed_before_GT=True,raw_hard_views='saved reward/tilted-target diagnostic readouts, not fitted model trials',oracle='metricwise fixed pair plus control; not online selector or bound on free-grid adaptation',scoring='unchanged official and independent scorer; dense Source spatial boxes fixed',primary='why B3 minus same-decoder marginal no-update has no established increment',Query_Consistency_remains_research_core=True,marginal_MAP_is_shared_readout=True,Actionness_restored=False,CURRENT_changed=False,independent_confirmation=False,raw_Query_Caption_GT_coordinates_media_weights_tensors_excluded=True))
